CREATE OR REPLACE FUNCTION public.validate_order_launch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s public.store_settings; BEGIN SELECT * INTO s FROM public.store_settings WHERE id=1; IF NOT s.checkout_open THEN RAISE EXCEPTION 'checkout_closed'; END IF; IF (new.payment_method='momo' AND trim(s.momo_number)='') OR (new.payment_method='bank' AND (trim(s.bank_name)='' OR trim(s.bank_account_number)='')) THEN RAISE EXCEPTION 'invalid_payment'; END IF; IF length(regexp_replace(new.phone,'\D','','g'))<9 OR length(new.customer_name)>120 OR length(new.address)>400 OR length(new.city)>80 OR new.zone NOT IN ('kumasi','ghana') OR new.locale NOT IN ('en','de') THEN RAISE EXCEPTION 'invalid_details'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_order_launch BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.validate_order_launch();
CREATE OR REPLACE FUNCTION public.validate_order_item_launch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.products; BEGIN SELECT * INTO p FROM public.products WHERE id=new.product_id; IF p.needs_review OR p.preorder OR NOT p.published THEN RAISE EXCEPTION 'unavailable:%',p.id; END IF; IF cardinality(p.sizes)>0 AND NOT(new.size=ANY(p.sizes)) THEN RAISE EXCEPTION 'invalid_size'; END IF; IF new.qty<1 OR new.qty>20 OR (p.kind='thrift' AND new.qty<>1) THEN RAISE EXCEPTION 'invalid_qty'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_order_item_launch BEFORE INSERT ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.validate_order_item_launch();
CREATE OR REPLACE FUNCTION public.validate_contact_message() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(new.name))<2 OR length(new.name)>120 OR length(trim(new.contact))<5 OR length(new.contact)>254 OR length(trim(new.message))<3 OR length(new.message)>5000 THEN RAISE EXCEPTION 'invalid_details'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_contact BEFORE INSERT OR UPDATE ON public.contact_messages FOR EACH ROW EXECUTE FUNCTION public.validate_contact_message();
CREATE OR REPLACE FUNCTION public.validate_quote_request() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(new.name))<2 OR length(new.name)>120 OR length(new.email)>254 OR new.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(trim(new.country))<2 OR length(new.country)>100 OR length(new.city)>100 OR length(new.phone)>40 OR length(trim(new.items))<3 OR length(new.items)>5000 THEN RAISE EXCEPTION 'invalid_details'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_quote BEFORE INSERT OR UPDATE ON public.quote_requests FOR EACH ROW EXECUTE FUNCTION public.validate_quote_request();